CREATE OR REPLACE FUNCTION public.enforce_paid_chat_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role()='service_role' AND (public.has_role(NEW.sender_id,'admin') OR public.has_role(NEW.receiver_id,'admin')) THEN RETURN NEW; END IF; IF NOT public.can_post_chat(NEW.post_id,NEW.receiver_id) AND NOT public.has_role(NEW.sender_id,'admin') THEN RAISE EXCEPTION 'PAID_CHAT_OR_PRIVATE_PAIR_REQUIRED'; END IF; RETURN NEW; END $$;